import cn from 'classnames';
import { TitleProps } from './title.types';

import './title.scss';

export function Title({ id, className, link, text, type }: TitleProps) {
  const Component = type;
  return (
    <div className={cn('title', className)}>
      <div data-cmp-data-layer="" id={id} className="cmp-title">
        <Component className="cmp-title__text">
          {link && link?.valid ? (
            <a className="cmp-title__link" data-cmp-clickable="" href={link.url} {...link.attributes}>
              {text}
            </a>
          ) : (
            text
          )}
        </Component>
      </div>
    </div>
  );
}

export default Title;
